const out = [];

// Pastas de reuniões já criadas nas pastas do mês (ex.: "2026-10-07 15h05-15h48 — Título")
const jaFeitas = ($('Drive - reuniões já processadas').first().json.files || []).map(f => f.name);

// Ordem de preferência da versão do vídeo gravado pelo Zoom
const videoPref = ['shared_screen_with_speaker_view', 'shared_screen_with_gallery_view', 'active_speaker', 'speaker_view', 'gallery_view', 'shared_screen'];

const toLocal = iso => new Date(iso).toLocaleString('sv-SE', { timeZone: 'America/Sao_Paulo', hour12: false });

for (const item of $input.all()) {
  const m = item.json;
  const all = m.recording_files || [];

  const files = all.filter(
    f => f.status === 'completed' && f.file_type === 'TRANSCRIPT'
  );

  for (const file of files) {
    const start = file.recording_start || m.start_time;
    const end = file.recording_end;

    const local = toLocal(start);
    const date = local.slice(0, 10);
    const time = local.slice(11, 16).replace(':', 'h');
    const timeEnd = end ? toLocal(end).slice(11, 16).replace(':', 'h') : '';
    const hora = timeEnd ? `${time}-${timeEnd}` : time;

    // Já processada em uma execução anterior? Pula.
    if (jaFeitas.some(n => n.startsWith(`${date} ${time}`))) continue;

    // Vídeo da mesma sessão de gravação da transcrição
    const videos = all.filter(f => f.status === 'completed' && f.file_type === 'MP4' && f.recording_start === file.recording_start);
    videos.sort((a, b) => {
      const ia = videoPref.indexOf(a.recording_type), ib = videoPref.indexOf(b.recording_type);
      return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib);
    });
    const video = videos[0] || null;

    const topic = (m.topic || 'Reunião')
      .replace(/[\\/:*?"<>|]/g, '-')
      .trim();

    out.push({
      json: {
        topic,
        date,
        time,
        timeEnd,
        sessionStart: file.recording_start,
        sessionEnd: file.recording_end,
        folderName: `ATA - ${topic} - ${date} - ${hora}`,
        video: video ? { download_url: video.download_url, file_size: video.file_size, recording_type: video.recording_type } : null,
        files: [file]
      }
    });
  }
}

return out;

const meetings = $('Preparar reunioes4').all();
const folders = $input.all();
const out = [];
folders.forEach((f, i) => {
  const m = meetings[i].json;
  for (const file of m.files) {
    out.push({ json: {
      folderId: f.json.id,
      folderName: m.folderName,
      file_type: file.file_type,
      download_url: file.download_url,
      videoUrl: m.video ? m.video.download_url : null
    }});
  }
});
return out;

const item = $input.item;
const meta = $('Expandir arquivos4').item.json;
const base = meta.folderName;
const buf = await this.helpers.getBinaryDataBuffer($itemIndex, 'data');
const vtt = buf.toString('utf8').replace(/\r/g, '');
const out = [];
let last = null;
for (const raw of vtt.split('\n')) {
  const l = raw.trim();
  if (!l || l === 'WEBVTT' || /^\d+$/.test(l) || l.includes('-->') || l.startsWith('NOTE')) continue;
  const m = l.match(/^([^:]{1,60}):\s(.*)$/);
  if (m) {
    if (last === m[1]) out[out.length - 1] += ' ' + m[2];
    else { out.push(m[1] + ': ' + m[2]); last = m[1]; }
  } else if (out.length) out[out.length - 1] += ' ' + l;
  else out.push(l);
}
const text = out.join('\n\n');
const fileName = `${base} - transcricao.txt`;
return {
  json: { fileName, folderId: meta.folderId, folderName: base, videoUrl: meta.videoUrl || null, isTranscript: true, text },
  binary: { data: await this.helpers.prepareBinaryData(Buffer.from(text, 'utf8'), fileName, 'text/plain') }
};

