const r = $json;
const raw = r?.candidates?.[0]?.content?.parts?.map(p => p.text || '').join('') || '';

if (!raw.trim()) {
  throw new Error('Gemini não retornou a ATA.');
}

let data;
try {
  data = JSON.parse(raw);
} catch (e) {
  const cleaned = raw
    .replace(/^```json\s*/i,'')
    .replace(/^```\s*/i,'')
    .replace(/```$/,'')
    .trim();
  try {
    data = JSON.parse(cleaned);
  } catch {
    throw new Error('Gemini não retornou JSON válido: ' + raw.slice(0,500));
  }
}

const meta = $('VTT para TXT4').item.json;

const title = String(data.titulo || 'Reunião')
  .replace(/[\\/:*?"<>|]/g,'-')
  .replace(/\s+/g,' ')
  .trim();

const assunto = String(data.assunto || 'Não informado').trim();

// folderName do Zoom: "ATA - tópico - 2026-10-07 - 15h05-15h48"
const m = String(meta.folderName || '').match(/(\d{4}-\d{2}-\d{2}) - (\d{2}h\d{2})(?:-(\d{2}h\d{2}))?/);
const date = m ? m[1] : '';
const time = m ? m[2] : '';
const timeEnd = m && m[3] ? m[3] : '';
const hora = timeEnd ? `${time}-${timeEnd}` : time;

// Pasta do mês: Meus Documentos / AAAA / TI / Gravações e Transcrições / MM
const mesKeys = $('Meses a garantir').all().map(i => i.json.key);
const mesIds = $('Drive - garantir pasta do mês').all().map(i => i.json.id);
const monthFolderId = mesIds[mesKeys.indexOf(date.slice(0, 7))];
if (!monthFolderId) throw new Error(`Pasta do mês não encontrada para a reunião de ${date}`);

// Ex.: "2026-10-07 15h05-15h48 — Fechamento fiscal"
const folderName = `${date} ${hora} — ${title}`.replace(/\s+/g,' ').trim();
const docName = folderName;
const docxName = `${folderName}.docx`;

const clean = v => String(v ?? '').replace(/\s*\n\s*/g,' ').trim();

const arr = v => Array.isArray(v)
  ? v.map(x => clean(x)).filter(Boolean)
  : [];

const textOrNI = v => clean(v) || 'Não informado';
const list = (v, fmt) => (arr(v).length ? arr(v) : ['Não informado']).map(fmt).join('\n');

const participantes = list(data.participantes, x => x);
const topicos = list(data.topicos, (x,i) => `${i+1}. ${x}`);
const estrategico = list(data.estrategico, x => `• ${x}`);
const tatico = list(data.tatico, x => `• ${x}`);
const operacional = list(data.operacional, x => `• ${x}`);
const decisoes = list(data.decisoes, x => `• ${x}`);
const problemas = list(data.problemas, x => `• ${x}`);
const solucoes = list(data.solucoes, x => `• ${x}`);

// Linhas das tabelas: uma linha por item real (as tabelas crescem no Docs conforme a quantidade).
const isObj = x => x && typeof x === 'object';
const etapas = (Array.isArray(data.proximasEtapas) ? data.proximasEtapas : [])
  .filter(isObj)
  .map(e => [textOrNI(e.nome), textOrNI(e.area), textOrNI(e.acao), textOrNI(e.prazo), textOrNI(e.prioridade)])
  .filter(row => row.some(c => c !== 'Não informado'));

const acoes = (Array.isArray(data.acoesDefinidas) ? data.acoesDefinidas : [])
  .filter(isObj)
  .map(a => [textOrNI(a.oQueSeraFeito), textOrNI(a.responsavel), textOrNI(a.proximoPasso), textOrNI(a.objetivo)])
  .filter(row => row.some(c => c !== 'Não informado'));

const dataBR = date ? date.split('-').reverse().join('/') : 'Não informado';

const replace = {
  TITULO: title,
  ASSUNTO: assunto,
  YOUTUBE_LINK: 'Não disponível',
  DATA: timeEnd ? `${dataBR} (${time} às ${timeEnd})` : dataBR,
  PARTICIPANTES: participantes,
  CONTEXTO: textOrNI(data.contexto),
  OBJETIVO: textOrNI(data.objetivo),
  TOPICOS: topicos,
  ESTRATEGICO: estrategico,
  TATICO: tatico,
  OPERACIONAL: operacional,
  DECISOES: decisoes,
  ANALISE_IA: textOrNI(data.analiseIA),
  CONSIDERACOES: textOrNI(data.consideracoes),
  PROBLEMAS: problemas,
  SOLUCOES: solucoes
};

return {
  json: {
    ...meta,
    title,
    assunto,
    folderName,
    docName,
    docxName,
    monthFolderId,
    templateGoogleDocId: $('Config4').first().json.templateGoogleDocId,
    replacements: replace,
    etapas,
    acoes,
    videoUrl: meta.videoUrl || null,
    videoName: `${folderName}.mp4`,
    transcriptText: meta.text,
    transcriptFileName: `Transcrição - ${date} ${hora}.txt`,
    etapaCount: etapas.length,
    acaoCount: acoes.length
  }
};

// Preenche as células das tabelas, coloca o link da transcrição e troca os {{PLACEHOLDERS}} do modelo.
const ata = $('Preparar ATA para Google Docs3').item.json;
const content = $json.body.content;
const pText = p => (p.paragraph?.elements || []).map(x => x.textRun?.content || '').join('');
const head = e => e.table ? e.table.tableRows[0].tableCells[0].content.map(pText).join('').trim() : null;

// Link da transcrição (.txt na pasta da reunião, com link aberto). Se falhou, usa o vídeo como antes.
let link = null;
let linkTexto = 'Abrir a transcrição da reunião';
let rotulo = 'Transcrição';
try {
  const id = $('Drive - salvar transcricao na pasta correta5').item.json.id;
  if (id) link = `<GOOGLE_URL>`;
} catch (e) {}
if (!link) {
  linkTexto = 'Assistir à gravação da reunião';
  rotulo = 'Gravação';
  try {
    const yt = $('YouTube - publicar vídeo (não listado)').item.json.uploadId;
    if (yt) { link = `https://youtu.be/${yt}`; rotulo = 'Gravação (YouTube)'; }
  } catch (e) {}
  if (!link) {
    try {
      const id = $('Drive - salvar vídeo').item.json.id;
      if (id) link = `<GOOGLE_URL>`;
    } catch (e) {}
  }
}

const tabelas = {
  'Nome': { rows: ata.etapas, vazio: 'Nenhuma próxima etapa foi definida na reunião.' },
  'O que será feito': { rows: ata.acoes, vazio: 'Nenhuma ação foi definida na reunião.' }
};

const ins = [];
for (const el of content) {
  const t = tabelas[head(el)];
  if (!t) continue;
  const tr = el.table.tableRows;
  if (!t.rows.length) {
    ins.push({ index: tr[1].tableCells[0].content[0].startIndex, text: t.vazio, italic: true });
    continue;
  }
  t.rows.forEach((vals, i) => {
    const row = tr[i + 1];
    if (!row) return;
    vals.forEach((v, c) => {
      const cell = row.tableCells[c];
      if (cell) ins.push({ index: cell.content[0].startIndex, text: String(v) });
    });
  });
}

// Troca {{YOUTUBE_LINK}} por um link clicável
const PH = '{{YOUTUBE_LINK}}';
const walk = (els, fn) => {
  for (const el of els || []) {
    if (el.paragraph) for (const pe of el.paragraph.elements || []) fn(pe);
    if (el.table) for (const r of el.table.tableRows) for (const c of r.tableCells) walk(c.content, fn);
  }
};
if (link) {
  walk(content, pe => {
    const txt = pe.textRun?.content || '';
    let k = txt.indexOf(PH);
    while (k >= 0) {
      ins.push({ index: pe.startIndex + k, text: linkTexto, link, removeLen: PH.length });
      k = txt.indexOf(PH, k + 1);
    }
  });
}

// De trás pra frente, para os índices não mudarem
ins.sort((a, b) => b.index - a.index);
const GRAY = { color: { rgbColor: { red: 0.13333334, green: 0.13333334, blue: 0.13333334 } } };
const BLUE = { color: { rgbColor: { red: 0.06666667, green: 0.33333334, blue: 0.8 } } };
const requests = [];
for (const x of ins) {
  const range = { startIndex: x.index, endIndex: x.index + x.text.length };
  if (x.link) {
    requests.push({ deleteContentRange: { range: { startIndex: x.index, endIndex: x.index + x.removeLen } } });
    requests.push({ insertText: { location: { index: x.index }, text: x.text } });
    requests.push({ updateTextStyle: {
      range,
      textStyle: { link: { url: x.link }, underline: true, bold: false, foregroundColor: BLUE, fontSize: { magnitude: 9, unit: 'PT' }, weightedFontFamily: { fontFamily: 'Arial' } },
      fields: 'link,underline,bold,foregroundColor,fontSize,weightedFontFamily'
    } });
    continue;
  }
  requests.push({ insertText: { location: { index: x.index }, text: x.text } });
  requests.push({ updateTextStyle: {
    range,
    textStyle: { bold: false, italic: !!x.italic, fontSize: { magnitude: 8, unit: 'PT' }, foregroundColor: GRAY, weightedFontFamily: { fontFamily: 'Arial' } },
    fields: 'bold,italic,fontSize,foregroundColor,weightedFontFamily'
  } });
}

const repl = { ...(ata.replacements || {}) };
if (link) delete repl.YOUTUBE_LINK;
for (const [key, value] of Object.entries(repl)) {
  requests.push({ replaceAllText: { containsText: { text: `{{${key}}}`, matchCase: true }, replaceText: String(value ?? '') } });
}
// Rótulo da linha do link: "Transcrição" (ou "Gravação" se a transcrição falhou)
if (rotulo !== 'Gravação (YouTube)') {
  requests.push({ replaceAllText: { containsText: { text: 'Gravação (YouTube)', matchCase: true }, replaceText: rotulo } });
}

return { json: { documentId: $json.documentId, requests } };

// Cria nas tabelas do Docs uma linha para cada etapa/ação real.
// Sem itens: junta as células da linha para mostrar uma mensagem.
const ata = $('Preparar ATA para Google Docs3').item.json;
const content = $json.body.content;
const pText = p => (p.paragraph?.elements || []).map(x => x.textRun?.content || '').join('');
const head = e => e.table ? e.table.tableRows[0].tableCells[0].content.map(pText).join('').trim() : null;

const specs = [
  { el: content.find(e => head(e) === 'Nome'), n: ata.etapas.length },
  { el: content.find(e => head(e) === 'O que será feito'), n: ata.acoes.length }
].filter(s => s.el).sort((a, b) => b.el.startIndex - a.el.startIndex);

const requests = [];
for (const s of specs) {
  const loc = { tableStartLocation: { index: s.el.startIndex }, rowIndex: 1, columnIndex: 0 };
  if (s.n === 0) {
    requests.push({ mergeTableCells: { tableRange: { tableCellLocation: loc, rowSpan: 1, columnSpan: s.el.table.columns } } });
  }
  for (let i = 1; i < s.n; i++) {
    requests.push({ insertTableRow: { tableCellLocation: loc, insertBelow: true } });
  }
}

// A API não aceita lista vazia
if (!requests.length) {
  requests.push({ replaceAllText: { containsText: { text: '{{__NADA__}}', matchCase: true }, replaceText: '' } });
}

return { json: { documentId: $json.documentId, requests } };

// Caminho: Meus Documentos / AAAA / TI / Gravações e Transcrições / MM
// Descobre quais pastas já existem (id) e quais precisam ser criadas (id = null).
const cfg = $('Config4').first().json;
const folders = $json.files || [];
const norm = s => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const child = (parentId, name) => parentId
  ? folders.find(f => (f.parents || []).includes(parentId) && norm(f.name) === norm(name))
  : null;

// Meses do período buscado no Zoom (ontem e hoje)
const byYear = {};
for (let i = cfg.daysBack; i >= 0; i--) {
  const d = $now.setZone('America/Sao_Paulo').minus({ days: i });
  (byYear[d.toFormat('yyyy')] ||= new Set()).add(d.toFormat('MM'));
}

return Object.entries(byYear).map(([year, months]) => {
  const y = child(cfg.baseFolderId, year);
  const ti = child(y?.id, cfg.tiFolderName);
  const gr = child(ti?.id, cfg.gravFolderName);
  return { json: {
    year,
    yearId: y?.id || null,
    tiId: ti?.id || null,
    gravId: gr?.id || null,
    months: [...months].map(mm => ({
      key: `${year}-${mm}`,
      name: mm,
      id: (child(gr?.id, mm) || child(gr?.id, '0' + mm))?.id || null
    }))
  } };
});

const anos = $('Resolver pastas do mês').all();
const out = [];
$input.all().forEach((it, i) => {
  for (const m of anos[i].json.months) {
    out.push({ json: { ...m, parentId: it.json.id }, pairedItem: { item: i } });
  }
});
return out;

// Manda para a lixeira do Zoom só as gravações cujas sessões (transcrições) JÁ têm ATA no Drive.
// Se alguma sessão da gravação ainda não tem ATA, a gravação fica no Zoom para tentar de novo.
const meetings = $('Zoom - listar gravacoes4').first().json.meetings || [];
const jaFeitas = ($('Drive - reuniões já processadas').first().json.files || []).map(f => f.name);
const feitasAgora = $('Preparar ATA para Google Docs3').all().map(i => i.json.folderName);
const nomes = [...jaFeitas, ...feitasAgora];
const toLocal = iso => new Date(iso).toLocaleString('sv-SE', { timeZone: 'America/Sao_Paulo', hour12: false });

const out = [];
for (const m of meetings) {
  const trans = (m.recording_files || []).filter(f => f.file_type === 'TRANSCRIPT' && f.status === 'completed');
  if (!trans.length) continue;
  const todas = trans.every(f => {
    const l = toLocal(f.recording_start || m.start_time);
    const chave = `${l.slice(0, 10)} ${l.slice(11, 16).replace(':', 'h')}`;
    return nomes.some(n => n.startsWith(chave));
  });
  if (!todas) continue;
  const uuidPath = (m.uuid.startsWith('/') || m.uuid.includes('//'))
    ? encodeURIComponent(encodeURIComponent(m.uuid))
    : encodeURIComponent(m.uuid);
  out.push({ json: { uuid: m.uuid, uuidPath, topic: m.topic, inicio: toLocal(m.start_time) } });
}
return out;
